import sys

MOD = 1000000007

def count_ways(n, k):
    if n == k:
        return 1
    if n <= k:
        return 0

    dp = [0] * (k + 1)
    dp[0] = 1

    for i in range(1, k + 1):
        dp[i] = (dp[i - 1] * (n - i + 1) % MOD + dp[i - 1]) % MOD

    result = (dp[k] ** (n - k)) % MOD
    return result

