from math import comb

def count_plaque_ways(n, k):
    MOD = 10**9 + 7
    if k == 1:
        return pow(3, n - 1, MOD)

    ways = 0
    for i in range(k):
        ways += comb(k, i) * pow(2, k - i - 1, MOD) * pow(3, n - k, MOD)
        ways %= MOD

    return ways

